68 38C686 29 703 44 703 60C703 69 698 76 689 80L155 333L689 586C698 590 703 597 703 606C703 623 695 631 679 631C675 631 671 630 668 629L94 357C84 352 79 344 79 333C79 322 84 315 94 310M678-72L100-72C84-72 76-80 76-95C76-111 84-119 100-119L678-119C694-119 702-111 702-95C702-83 691-72 678-72Z"></path></g><g data-mml-node="mn" data-latex="0" transform="translate(2821.6,0)"><path data-c="30" d="M249-22C390-22 460 92 460 320C460 473 428 575 365 625C330 652 291 666 250 666C109 666 39 551 39 320C39 136 88-22 249-22M361 524C368 489 371 425 371 332C371 240 367 172 360 128C347 48 310 8 249 8C226 8 203 17 182 34C155 57 139 104 132 176C129 201 128 253 128 332C128 419 131 480 136 513C145 568 163 603 191 618C213 630 232 636 249 636C314 636 350 583 361 524Z"></path></g></g></g></g><g data-mml-node="mo" transform="translate(11259.1,0) translate(0 250)"></g></g></g></g></svg><mjx-assistive-mml unselectable="on" display="block"><math xmlns="http://www.w3.org/1998/Math/MathML" data-latex="f(x) = \begin{cases}x &amp; \text{if } x > 0 \\alpha x &amp; \text{if } x \leq 0\end{cases}" display="block"><mi data-latex="f">f</mi><mo data-latex="(" stretchy="false">(</mo><mi data-latex="x">x</mi><mo data-latex=")" stretchy="false">)</mo><mo data-latex="=">=</mo><mrow data-mjx-texclass="INNER" data-latex-item="{cases}" data-latex="{cases}"><mo data-mjx-texclass="OPEN">{</mo><mtable columnspacing="1em" rowspacing=".2em" columnalign="left left"><mtr><mtd><mi data-latex="x">x</mi></mtd><mtd><mtext data-latex="\text{if }">if </mtext><mi data-latex="x">x</mi><mo data-latex=">">&gt;</mo><mn data-latex="0">0</mn><mtext> </mtext><mi data-latex="\alpha">α</mi><mi data-latex="x">x</mi></mtd><mtd><mtext data-latex="\text{if }">if </mtext><mi data-latex="x">x</mi><mo data-latex="\leq">≤</mo><mn data-latex="0">0</mn></mtd></mtr></mtable><mo data-mjx-texclass="CLOSE" fence="true" stretchy="true" symmetric="true"></mo></mrow></math></mjx-assistive-mml></mjx-container><figure><img src="@source/深度学习/一文搞懂激活函数在深度学